from datetime import datetime, timezone

NEEDS = {
    "venue": "kalshi",
    "horizon": "day",
    "style": "rain-favorites-no-safety",
    "series": ["KXRAIN", "KXRAINDNYC"],
    "max_hours_to_close": 12,
    "wake_minutes": 60,
}
PARAMS = {
    "bid_min": 0.90,
    "bid_max": 0.97,
    "max_spread": 0.03,
    "min_hours": 1.0,
    "max_hours": 12.0,
    "min_volume_24h": 1000.0,
    "notional_usd": 10.0,
    "max_open": 6,
    "requote_minutes": 180.0,
}
EPS = 1e-9

def num(x, default=None):
    try:
        y = float(x)
        if y != y or abs(y) == float("inf"):
            return default
        return y
    except (TypeError, ValueError):
        return default

def when(x):
    try:
        s = str(x).strip()
        if s.endswith("Z") or s.endswith("z"):
            s = s[:-1] + "+00:00"
        d = datetime.fromisoformat(s)
        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
    except (TypeError, ValueError):
        return None

def decide(ctx):
    p = dict(PARAMS)
    p.update(ctx.get("params") or {})
    def knob(k):
        return num(p.get(k), PARAMS[k])

    now = when(ctx.get("now"))
    positions = [x for x in (ctx.get("positions") or [])
                 if isinstance(x, dict) and (num(x.get("quantity"), 0.0) or 0.0) > 0]
    orders = [x for x in (ctx.get("open_orders") or []) if isinstance(x, dict)]
    busy = {str(x.get("market")) for x in positions}
    busy.update(str(x.get("market")) for x in orders)
    cancels = []
    for o in orders:
        submitted = when(o.get("submitted_at"))
        if o.get("order_id") and submitted is not None and now is not None:
            age = (now - submitted).total_seconds() / 60.0
            if age > knob("requote_minutes"):
                cancels.append(str(o["order_id"]))

    risk = ctx.get("event_risk") or {}
    remaining = risk.get("remaining_by_market_usd") or {}
    found = []
    for m in (ctx.get("markets") or []):
        if not isinstance(m, dict) or not m.get("market"):
            continue
        yb = num(m.get("yes_bid"))
        ya = num(m.get("yes_ask"))
        hc = num(m.get("hours_to_close"))
        hr = num(m.get("hours_to_resolve"))
        vol = num(m.get("volume_24h"), 0.0)
        if yb is None or ya is None or hc is None or hr is None:
            continue
        if not (0.0 < yb < ya < 1.0):
            continue
        no_bid = round(1.0 - ya, 4)
        no_ask = round(1.0 - yb, 4)
        if no_bid < knob("bid_min") - EPS or no_bid > knob("bid_max") + EPS:
            continue
        if no_ask - no_bid > knob("max_spread") + EPS:
            continue
        if hc < knob("min_hours") or hc > knob("max_hours"):
            continue
        if hr > 48.0 or vol < knob("min_volume_24h"):
            continue
        ticker = str(m["market"])
        if ticker in busy:
            continue
        capacity = num(remaining.get(ticker), None)
        if capacity is not None and capacity < 1.0:
            continue
        price = round(no_bid - 0.01, 2)
        if price < knob("bid_min") or price >= no_ask:
            continue
        found.append((-vol, ticker, price, hc, hr, capacity))
    found.sort()

    limits = ctx.get("limits") or {}
    equity = num(ctx.get("equity"), 0.0) or 0.0
    cash = num(ctx.get("cash"), 0.0) or 0.0
    reserved = sum((num(o.get("quantity"), 0.0) or 0.0) *
                   (num(o.get("limit_price"), 0.0) or 0.0)
                   for o in orders if o.get("side") == "buy")
    free = max(0.0, cash - reserved) * 0.98
    cap = min(knob("notional_usd"),
              num(limits.get("max_order_usd"), knob("notional_usd")),
              num(limits.get("max_position_usd"), knob("notional_usd")))
    if equity > 0:
        cap = min(cap, 0.30 * equity)
    slots = max(0, min(8, int(knob("max_open")) - len(busy)))
    intents = []
    for _, ticker, price, hc, hr, capacity in found:
        if len(intents) >= slots:
            break
        allowed = min(cap, free)
        if capacity is not None:
            allowed = min(allowed, capacity)
        qty = int(allowed / price + EPS)
        if qty < 1 or qty * price < 1.0:
            continue
        free -= qty * price
        intents.append({
            "market": ticker,
            "leg": "no",
            "side": "buy",
            "quantity": qty,
            "type": "limit",
            "limit_price": price,
            "post_only": True,
            "reason": "Rain-market NO favourite; resting one-cent below the current NO bid to avoid post-only crosses, with resolution within 48 hours and available event capacity.",
        })
    return {
        "intents": intents,
        "cancels": cancels,
        "thought": "Restricted to rain favourites and applied resolution, capacity, cash, and non-crossing post-only safeguards.",
        "memory": {},
    }

